#define main toe_free_admission_main
#include "toe_model.cpp"
#undef main
#include "wing_model.hpp"
#include <fstream>
#include <cstring>
#include <map>
int main(){RunManifest m;m.id="capture_map";m.robot=toeModel();crowResearchWingInertia(m.robot);m.scene=makeBirdFlowAmericanCrowFlightScenePack();auto& b=m.scene.objects.at(0).mechanics.shapes.at(0);b.shapeType=MR_SHAPE_BOX;b.localPosition={0,0,0,1};b.localRotation={0,0,0,1};b.dimensions={.025f,.72f,.055f,0};b.contactRestAndBoundingRadius.z=std::sqrt(.025f*.025f+.72f*.72f+.055f*.055f);for(auto&shape:m.robot.mechanics.shapes)shape.flags|=MR_SHAPE_FLAG_ENABLE_CCD;m.sensors.id="proprioception";m.task=makeAmericanCrowEmbodiedTaskPack(m.sensors.observation,m.reality.reset);m.reality.reset={};m.reality.id="reality";m.teacher.id="no_teacher";m.profile.id="probe";m.profile.capacities={.candidatePairs=512,.rawContacts=2048,.manifolds=512,.constraintBlocks=2048,.constraintRows=6144};m.task.capacities=m.profile.capacities;m.profile.environmentCount=1;m.profile.controlSteps=160;m.profile.physicsSubsteps=1;m.profile.controlTimestepSeconds=.005f;CompiledRun run;auto st=compileRun(m,run);need(st.succeeded(),st.message);
 std::ifstream f("artifacts/crow-v15-hybrid-ccd-failure-20261110/ccd-failure.bin",std::ios::binary);char magic[8];unsigned h[6];f.read(magic,8);f.read((char*)h,sizeof(h));need(bool(f)&&std::memcmp(magic,"CCDSNP01",8)==0,"snapshot header");std::map<std::string,std::vector<char>> data;for(unsigned i=0;i<h[5];i++){char tag[9]{};uint64_t n;f.read(tag,8);f.read((char*)&n,8);need(n<1024*1024,"oversize");auto& bytes=data[tag];bytes.resize(n);f.read(bytes.data(),n);}need(bool(f),"snapshot body");auto&pairData=data.at("pairs");need(pairData.size()%sizeof(MRCompiledCollisionPairGPU)==0,"pair layout");auto* pairs=(const MRCompiledCollisionPairGPU*)pairData.data();need(h[4]<pairData.size()/sizeof(*pairs),"pair index");auto pair=pairs[h[4]];const auto& model=run.model();std::cout<<"pair "<<h[4]<<" collider_a "<<pair.colliderA<<" "<<model.shapeNames.at(pair.colliderA)<<" type "<<model.shapes.at(pair.colliderA).shapeType<<" collider_b "<<pair.colliderB<<" "<<model.shapeNames.at(pair.colliderB)<<" type "<<model.shapes.at(pair.colliderB).shapeType<<std::endl;
 auto& failure=data.at("failed");need(failure.size()==sizeof(MRCCDFailureSnapshotGPU),"failure layout");MRCCDFailureSnapshotGPU x;std::memcpy(&x,failure.data(),sizeof(x));auto c=x.candidate;auto e=x.event;std::cout<<"candidate flags "<<c.flags<<" status "<<c.status<<" interval "<<c.intervalAndDistance.x<<" "<<c.intervalAndDistance.y<<" "<<c.intervalAndDistance.z<<" "<<c.intervalAndDistance.w<<" normal "<<c.normalAndIteration.x<<" "<<c.normalAndIteration.y<<" "<<c.normalAndIteration.z<<" iterations "<<c.normalAndIteration.w<<" event "<<e.splitCount<<" zero "<<e.zeroTimeReplayCount<<" time "<<e.time.x<<" "<<e.time.y<<" "<<e.time.z<<" "<<e.time.w<<std::endl;
}
